create or replace TABLE LDL_DATA_PRODUCTION.CORE_APP_FRAUD_DETECTION.T_CASH_REGISTER_PRINT cluster by (BUS_DT)(
	CASH_REGISTER_EVENT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the related cash register event. Depending on the scenario, it references a retail event, a price lookup event or a technical cash register event.',
	CASH_REGISTER_EVENT_NR VARCHAR(20) NOT NULL COMMENT 'The sequence number of the cash register transaction. It is unique to the cash register, but might be re-cycled after some time.',
	CASHIER_NR VARCHAR(20) NOT NULL COMMENT 'The number which identifies the cashier. (The number is unique for a given store and a day.)',
	CASH_REGISTER_EVENT_LINE_SEQ NUMBER(38,0) NOT NULL COMMENT 'The number of the line in the retail event, in the case of the techical event or price information event is the value always \""-1\""',
	EVENT_AUTH_BY_NR VARCHAR(20) COMMENT 'In case of a cancellation or any other non-standard operation, the transaction must be authorized by the store manager or by another employee. This is the number which identifies the employee, who has authorized the transaction. (This is not an employee number!)',
	PARENT_LINE_SEQ NUMBER(38,0) NOT NULL COMMENT 'In case the line represents a deposit, this is the related base line.',
	CASH_REGISTER_EVENT_SCENARIO_ID NUMBER(38,0) NOT NULL COMMENT 'The code identifying all kinds of cash register event (technical or retail event).',
	RETAIL_EVENT_LINE_SCENARIO_ID NUMBER(38,0) COMMENT 'The numeric identifier for the scenario which is represented by the retail event line.',
	EVENT_START_TMSP TIMESTAMP_TZ(9) COMMENT 'The point in time when the retail event started.',
	EVENT_END_TMSP TIMESTAMP_TZ(9) COMMENT 'The end timestamp of the retail event.',
	EVENT_LINE_START_TMSP TIMESTAMP_TZ(9) COMMENT 'The point in time when the retail event line started.',
	EVENT_LINE_END_TMSP TIMESTAMP_TZ(9) COMMENT 'The end timestamp of the retail event line.',
	BUS_DT DATE COMMENT 'The business date on which the retail event is counted.',
	STORE_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for the store where the related retail event happend.',
	STORE_NR VARCHAR(20) COMMENT 'The identifier for the store where the related retail event happend.',
	COUNTRY_ORG_CD VARCHAR(2) COMMENT 'The code of the related business country. (The business country is not identical to a political country.)',
	CASH_REGISTER_NR VARCHAR(20) COMMENT 'The number which identifies the cash register.',
	PROD_RETAIL_LINE_TYPE_CD VARCHAR(20) COMMENT 'The code identifying the subtype discriminator for product retail lines.',
	PROD_VARIANT_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for a sales variant of a product.',
	LOCAL_PROD_NR VARCHAR(100) COMMENT 'The number which identifies the product in the operational retail management system within the given market / internal organization (i.e. the local item number).  Note that the product number is unique for a certain point in time, but may be re-used later on. One product may be identified by several numbers in case of parallel listings or rolling listings. This is the number which has been configured in the cash registers of the given stores for the point in time when the retail transaction was made.',
	PROD_VARIANT_INPUT_NR VARCHAR(100) COMMENT 'The number which identifies the product variant - as it has been scanned or manually keyed this. This can be an EAN, GTIN or a price lookup number (PLU)',
	PROD_VARIANT_INPUT_NR_TYPE_CD VARCHAR(20) COMMENT 'The code identifying the kind of the number which has been scanned or typed in, in order to identify the product variant. The product variant number can be identified by an EAN, a GTIN or a product lookup number (PLU).',
	PROD_NAME VARCHAR(250) COMMENT 'The name of the global product, which is the base for this sales variant.',
	PROD_ENTRY_METHOD_CD VARCHAR(20) COMMENT 'The code identifying the way, how the product was entered into the cash register, i.e. if the product is scanned, or if it is entered via the keyboard.',
	PRICE_ENTRY_METHOD_CD VARCHAR(20) COMMENT 'The code identifying the way, how the unit price was entered into the cash register, i.e. if the product is scanned, or if it is entered via the keyboard.',
	PAYM_LINE_TYPE_CD VARCHAR(20) COMMENT 'The code identifying the subtype discriminator for payment lines. It distinguishes between incoming and outgoing payments, i.e. payments made by the customer and payments made to the customer.',
	PAYM_TYPE_ID NUMBER(38,0) COMMENT 'The identifier for the way of payment, i.e. cash, card, voucher, etc.',
	FRAUD_DETECTION_RELEVANT_FG BOOLEAN COMMENT 'The identifier of fraud detection relevant receipts.',
	PROD_RETURN_REASON_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for the reasons why a product was returend to the store.',
	RETURN_TXT VARCHAR(1000) COMMENT 'A free text field describing the circumstances of the return.',
	PARENT_RETAIL_EVENT_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for the related retail transaction, i.e. for the sales or return of products..',
	DISCOUNT_FG BOOLEAN COMMENT 'An indicator showing, if a discount or a price modification was applied to the product.',
	UNIT_PRICE NUMBER(38,5) COMMENT 'The price of a single unit of the product variant, in the currency indicated by the currency code.',
	PROD_VARIANT_CNT NUMBER(38,0) COMMENT 'The number of this product variant which has been sold or returned. (This attribute is empty for weight-based products.)',
	PROD_VARIANT_QTY NUMBER(38,5) COMMENT 'In case of weight-based products, this is the quantity of the product which was sold or returned.',
	BASE_GROSS_VAL NUMBER(38,5) COMMENT 'The base gross amount of the sales or return, i.e. quantity / count * unit price. Discounts or price modifications are not considered.',
	RETAIL_LINE_GROSS_VAL NUMBER(38,5) COMMENT 'The gross amount of the sales or return, i.e. quantity / count * unit price. Discounts and price changes are considered.',
	RETAIL_LINE_VAT_VAL NUMBER(38,5) COMMENT 'The total amount of value added tax which was charged for this line.',
	LOCAL_PAYM_VAL NUMBER(38,5) COMMENT 'The amount which was paid in local currency. If the amount was paid by the customer, the sign is positive. If the amount was paid to the customer, the sign is negative. If the payment was in a foreign currency, this is the local currency equivalent.',
	TAX_PCT NUMBER(38,5) COMMENT 'The actual tax percentage which is valid for the given tax class. E.g. 19% and also for the products which got sold.',
	CASH_REGISTER_EVENT_SEQ NUMBER(38,0) NOT NULL COMMENT 'Is a sequence number partition by: real_estate_sid ,bus_dt ,cashier_hash and order by event_end_tmsp.',
	DWH_CREATED_TMSP TIMESTAMP_TZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_TZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	LINE_AUTH_BY_NR VARCHAR(20) COMMENT 'In case of a cancellation or any other non-standard operation, the transaction line must be authorized by the store manager or by another employee. This is the number which identifies the employee, who has authorized the transaction line. (This is not an employee number!)',
	ORIG_COUNTRY_ORG_CD VARCHAR(2) COMMENT 'In case of the return the customer needs to provide the original receipt, this column contains the country information of the original receipt.',
	ORIG_STORE_NR VARCHAR(20) COMMENT 'In case of the return the customer needs to provide the original receipt, this columns contains the store number of the original receipt.',
	ORIG_BUS_DT DATE COMMENT 'In case of the return the customer needs to provide the original receipt, this columns contains the business date of the original receipt.',
	ORIG_CASH_REGISTER_NR NUMBER(38,0) COMMENT 'In case of the return the customer needs to provide the original receipt, this columns contains the cash register number of the original receipt.',
	ORIG_CASH_REGISTER_EVENT_NR NUMBER(38,0) COMMENT 'In case of the return the customer needs to provide the original receipt, this columns contains the cash register number of the original receipt.',
	FIRST_LINE_OF_EVENT_FG BOOLEAN NOT NULL COMMENT 'Displays the first line of the receipt. Due to the sitaution that sometimes we receive lines with number \""0\"". ',
	TAX_LINE_GROSS_VAL NUMBER(38,5) COMMENT 'That is the base gross value, which is the base for the VAT calculation.',
	TAX_LINE_VAL NUMBER(38,5) COMMENT 'The resulting tax amount.',
	constraint PK_T_CASH_REGISTER_PRINT primary key (CASH_REGISTER_EVENT_SID, CASH_REGISTER_EVENT_LINE_SEQ, PARENT_LINE_SEQ)
)COMMENT='Keeps the cash register events which are identificated for fraud detection and pre- and post receipts for printout.'
;